action_input.code:
import csv

# Find Alex Yoong's races from driverStandings.csv
yoong_races = []
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['driverId'] == '62':
            yoong_races.append(row['raceId'])

print(f"Alex Yoong participated in {len(yoong_races)} races")
print(f"Race IDs: {yoong_races[:10]}...")

# Now get race details including round number
races_info = {}
with open('csv/races.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        races_info[row['raceId']] = row

# Filter races with round < 20
results = []
for race_id in yoong_races:
    if race_id in races_info:
        race = races_info[race_id]
        round_num = int(race['round'])
        if round_num < 20:
            results.append({
                'raceId': race_id,
                'round': round_num,
                'name': race['name'],
                'year': race['year']
            })

print(f"\nRaces with round < 20:")
for r in results:
    print(r)

